  constructor(agentOrchestrator, uep) {
    this.agentOrchestrator = agentOrchestrator;
    this.uep = uep;
    this.app = express();
    this.setupRoutes();
  }

  setupRoutes() {
    this.app.post('/api/workflows/:workflow', async (req, res) => {
      try {
        const { workflow } = req.params;
        const params = req.body;
