import { RedisSearchCache } from './redis-search-cache';
import { InMemoryCache } from './in-memory-cache';

export class CacheManager implements CacheManager {
  private redisCache: RedisSearchCache;
  private memoryCache: InMemoryCache;

  constructor(redisConfig: RedisConfig, memoryCacheOptions?: CacheOptions) {
    this.redisCache = new RedisSearchCache(redisConfig);
    this.memoryCache = new InMemoryCache(memoryCacheOptions);
  }

  public async getCachedSearch(queryHash: string): Promise<SearchResult[] | null> {
    // Try memory cache first for fastest access
    const memoryResults = this.memoryCache.getCachedQueryPattern(queryHash);
    if (memoryResults) return memoryResults;

    // Fall back to Redis cache
    const redisResults = await this.redisCache.getCachedSearch(queryHash);
    if (redisResults) {
      // Populate memory cache for faster future access
      this.memoryCache.setCachedQueryPattern(queryHash, redisResults);
      return redisResults;
    }

    return null;
  }

  public async setCachedSearch(queryHash: string, results: SearchResult[], ttl?: number): Promise<void> {
    // Determine content type for TTL
    const contentType = this.determineContentType(results);

    // Cache in both layers
    await this.redisCache.setCachedSearch(queryHash, results, contentType, ttl);
    this.memoryCache.setCachedQueryPattern(queryHash, results);
  }

  public async getCachedEmbedding(content: string): Promise<number[] | null> {
    return this.memoryCache.getCachedEmbedding(content);
  }

  public async setCachedEmbedding(content: string, embedding: number[]): Promise<void> {
    this.memoryCache.setCachedEmbedding(content, embedding);
  }

  public async getCachedFileContent(filePath: string): Promise<ProcessedFile | null> {
    return this.memoryCache.getCachedFileContent(filePath);
  }

  public async setCachedFileContent(filePath: string, content: ProcessedFile): Promise<void> {
    this.memoryCache.setCachedFileContent(filePath, content);
  }

  public async invalidateFile(filePath: string): Promise<void> {
    // Clear file from memory cache
    this.memoryCache.invalidateFile(filePath);

    // Clear related queries from Redis
    await this.redisCache.invalidateRelatedToFile(filePath);
  }

  public async invalidatePattern(pattern: string): Promise<void> {
    // Clear pattern matches from both caches
    await this.redisCache.invalidatePattern(pattern);
    this.memoryCache.invalidatePattern(pattern);
  }

  public async clearCache(): Promise<void> {
    await this.redisCache.clear();
    this.memoryCache.clear();
  }

  public async getStats(): Promise<CacheStats> {
    const memoryStats = this.memoryCache.getStats();
    const redisStats = await this.redisCache.getStats();

    return {
      memory: memoryStats,
      redis: redisStats,
      combined: {
        hits: memoryStats.hits + redisStats.hits,
        misses: memoryStats.misses + redisStats.misses,
        hitRate: (memoryStats.hits + redisStats.hits) / 
                (memoryStats.hits + redisStats.hits + memoryStats.misses + redisStats.misses)
      }
    };
  }

  private determineContentType(results: SearchResult[]): 'file' | 'static' {
    // Logic to determine if results are from files or static docs
    const fileResults = results.filter(r => r.source.type === 'file');
    return fileResults.length > results.length / 2 ? 'file' : 'static';
  }
}
