Develop a comprehensive cache invalidation system with the following components:

1. Use chokidar v3.5.3 (latest stable) for file watching
2. Implement git hook integration using simple-git v3.20.0
3. Create timestamp verification for file modifications
4. Implement semantic similarity-based invalidation for related queries
5. Add pattern matching for file-based invalidation
6. Create CLI commands for manual cache invalidation

Example implementation:
```typescript
import chokidar from 'chokidar';
import simpleGit from 'simple-git';
import { CacheManager } from './cache-manager';
import { getSimilarQueries } from './semantic-utils';

export class CacheInvalidator implements CacheInvalidator {
  private cacheManager: CacheManager;
  private watcher: chokidar.FSWatcher | null = null;
  private git = simpleGit();
  private fileChangeCallbacks: ((filePath: string) => Promise<void>)[] = [];
  private gitChangeCallbacks: ((changedFiles: string[]) => Promise<void>)[] = [];

  constructor(cacheManager: CacheManager) {
    this.cacheManager = cacheManager;
  }

  public watchFiles(patterns: string[]): void {
    // Close existing watcher if any
    if (this.watcher) {
      this.watcher.close();
    }

    // Initialize file watcher
    this.watcher = chokidar.watch(patterns, {
      persistent: true,
      ignoreInitial: true,
      awaitWriteFinish: {
        stabilityThreshold: 300,
        pollInterval: 100
      }
    });

    // Handle file changes
    this.watcher.on('change', async (filePath) => {
      console.log(`File changed: ${filePath}`);
      await this.handleFileChange(filePath);
    });

    this.watcher.on('unlink', async (filePath) => {
      console.log(`File deleted: ${filePath}`);
      await this.handleFileChange(filePath);
    });

    // Setup git hooks
    this.setupGitHooks();
  }

  public onFileChange(callback: (filePath: string) => Promise<void>): void {
    this.fileChangeCallbacks.push(callback);
  }

  public onGitChange(callback: (changedFiles: string[]) => Promise<void>): void {
    this.gitChangeCallbacks.push(callback);
  }

  public async invalidateRelatedQueries(filePath: string): Promise<void> {
    // Get cached queries that might be related to this file
    const cachedQueries = await this.cacheManager.getCachedQueries();

    // Find semantically similar queries to the file content
    const fileContent = await this.getFileContent(filePath);
    if (!fileContent) return;

    const similarQueries = await getSimilarQueries(fileContent, cachedQueries, 0.7); // 0.7 similarity threshold

    // Invalidate similar queries
    for (const query of similarQueries) {
      await this.cacheManager.invalidateQuery(query);
    }

    // Also invalidate by pattern matching
    const filePattern = this.getFilePattern(filePath);
    await this.cacheManager.invalidatePattern(filePattern);
  }

  private async handleFileChange(filePath: string): Promise<void> {
    // Invalidate file in cache
    await this.cacheManager.invalidateFile(filePath);

    // Invalidate related queries
    await this.invalidateRelatedQueries(filePath);

    // Notify callbacks
    for (const callback of this.fileChangeCallbacks) {
      await callback(filePath);
    }
  }

  private async setupGitHooks(): Promise<void> {
    // Watch for git branch changes
    try {
      const currentBranch = await this.git.revparse(['--abbrev-ref', 'HEAD']);

      // Poll for branch changes (simple approach)
      setInterval(async () => {
        const newBranch = await this.git.revparse(['--abbrev-ref', 'HEAD']);
        if (newBranch !== currentBranch) {
          console.log(`Git branch changed: ${currentBranch} -> ${newBranch}`);
          await this.handleGitBranchChange(newBranch, currentBranch);
        }
      }, 5000); // Check every 5 seconds
    } catch (error) {
      console.error('Failed to setup git hooks:', error);
    }
  }

  private async handleGitBranchChange(newBranch: string, oldBranch: string): Promise<void> {
    try {
      // Get changed files between branches
      const diff = await this.git.diff([`${oldBranch}...${newBranch}`, '--name-only']);
      const changedFiles = diff.split('\n').filter(Boolean);

      // Clear cache for changed files
      for (const file of changedFiles) {
        await this.cacheManager.invalidateFile(file);
      }

      // Notify callbacks
      for (const callback of this.gitChangeCallbacks) {
        await callback(changedFiles);
      }
    } catch (error) {
      console.error('Failed to handle git branch change:', error);
    }
  }

  private getFilePattern(filePath: string): string {
    // Extract pattern from file path (e.g., *.ts, src/components/*)  
    const parts = filePath.split('/');
    const fileName = parts[parts.length - 1];
    const extension = fileName.includes('.') ? fileName.split('.').pop() : '';

    return extension ? `*.${extension}` : fileName;
  }

  private async getFileContent(filePath: string): Promise<string | null> {
    try {
      const fs = await import('fs/promises');
      return await fs.readFile(filePath, 'utf-8');
    } catch (error) {
      console.error(`Failed to read file ${filePath}:`, error);
      return null;
    }
  }
}
```

