      // Warm cache in background
      this.warmQueriesInBackground(queries, 'conversation');
    } catch (error) {
      console.error(`Error warming conversation context: ${error}`);
    }
  }

  public scheduleWarming(schedule: WarmingSchedule): void {
    // Clear existing schedule if any
    if (this.warmingSchedules.has(schedule.id)) {
      clearInterval(this.warmingSchedules.get(schedule.id)!);
    }

    // Schedule new warming task
    const interval = setInterval(async () => {
      try {
        switch (schedule.type) {
          case 'project':
            await this.warmProjectContext(schedule.target);
            break;
          case 'agent':
            await this.warmAgentContext(schedule.target);
            break;
          case 'conversation':
            await this.warmConversationContext(schedule.target);
            break;
        }
      } catch (error) {
        console.error(`Error in scheduled warming: ${error}`);
      }
    }, schedule.intervalMs);

    this.warmingSchedules.set(schedule.id, interval);
  }

  private async getCommonProjectQueries(projectPath: string): Promise<string[]> {
