    return commonAgentQueries[agentType] || [];
  }

  private async getConversationHistory(conversationId: string): Promise<any[]> {
    // This would fetch from a conversation store
    // Mock implementation for now
    return [];
  }

  private extractQueriesFromConversation(history: any[]): string[] {
    // Extract potential queries from conversation history
    // This would use NLP to identify information needs
    // Simplified implementation for now
    return history
      .filter(msg => msg.role === 'user')
      .map(msg => msg.content)
      .filter(content => content.length > 10 && content.length < 200);
  }

  private async warmProjectFiles(projectPath: string): Promise<void> {
    // Get important project files
    const importantFiles = await this.getImportantProjectFiles(projectPath);

    // Process files in batches to avoid overwhelming the system
    const batchSize = 5;
    for (let i = 0; i < importantFiles.length; i += batchSize) {
      const batch = importantFiles.slice(i, i + batchSize);
      await Promise.all(batch.map(file => this.processFile(file)));
    }
  }

  private async getImportantProjectFiles(projectPath: string): Promise<string[]> {
    try {
      const { glob } = await import('glob');

      // Find important files like READMEs, package.json, etc.
      const patterns = [
        `${projectPath}/**/README.md`,
        `${projectPath}/**/package.json`,
        `${projectPath}/**/*.config.js`,
        `${projectPath}/src/index.*`,
        `${projectPath}/src/main.*`
      ];

      const files = await glob(patterns);
      return files;
    } catch (error) {
      console.error('Error finding important project files:', error);
      return [];
    }
  }

  private async processFile(filePath: string): Promise<void> {
    try {
      // Read file content
      const fs = await import('fs/promises');
      const content = await fs.readFile(filePath, 'utf-8');

      // Process and cache file content
      const processedFile = await this.ragService.processFile(filePath, content);
      await this.cacheManager.setCachedFileContent(filePath, processedFile);

      // Generate and cache embedding
      const embedding = await this.ragService.generateEmbedding(content);
      await this.cacheManager.setCachedEmbedding(content, embedding);
    } catch (error) {
      console.error(`Error processing file ${filePath}:`, error);
    }
  }

  private warmQueriesInBackground(queries: string[], contextType: string): void {
    // Use a worker thread or background process for warming
    // Simplified implementation using setTimeout for now
    setTimeout(async () => {
      console.log(`Starting background warming for ${contextType} context with ${queries.length} queries`);

      let completed = 0;
      for (const query of queries) {
        try {
          // Execute query and cache results
          const results = await this.ragService.search(query);
          const queryHash = this.generateQueryHash(query);
          await this.cacheManager.setCachedSearch(queryHash, results);

          completed++;
          if (completed % 5 === 0 || completed === queries.length) {
            console.log(`Warming progress: ${completed}/${queries.length} queries completed`);
          }
        } catch (error) {
          console.error(`Error warming query '${query}':`, error);
        }
      }

      console.log(`Completed warming ${contextType} context with ${completed}/${queries.length} successful queries`);
    }, 0);
  }

  private generateQueryHash(query: string): string {
    const crypto = require('crypto');
    return crypto.createHash('sha256').update(query).digest('hex');
  }
}
