import { CacheManager } from '../cache/cache-manager';
import { VectorDBService } from './vector-db-service';
import { EmbeddingService } from './embedding-service';
import { DocumentProcessor } from './document-processor';

export class CachedRAGService implements RAGService {
  private cacheManager: CacheManager;
  private vectorDB: VectorDBService;
  private embeddingService: EmbeddingService;
  private documentProcessor: DocumentProcessor;

  constructor(
    cacheManager: CacheManager,
    vectorDB: VectorDBService,
    embeddingService: EmbeddingService,
    documentProcessor: DocumentProcessor
  ) {
    this.cacheManager = cacheManager;
    this.vectorDB = vectorDB;
    this.embeddingService = embeddingService;
    this.documentProcessor = documentProcessor;
  }

  public async search(query: string, filters?: any, topK: number = 10): Promise<SearchResult[]> {
    const startTime = Date.now();

    try {
      // Generate query hash
      const queryHash = this.generateQueryHash(query, filters, topK);

      // Check cache first
      const cachedResults = await this.cacheManager.getCachedSearch(queryHash);
      if (cachedResults) {
        console.log(`Cache hit for query: ${query}`);
        this.recordMetrics('search', 'hit', Date.now() - startTime);
        return cachedResults;
      }

      console.log(`Cache miss for query: ${query}`);

      // Generate embedding (with caching)
      const embedding = await this.generateEmbedding(query);

      // Perform vector search
      const results = await this.vectorDB.search(embedding, filters, topK);

      // Cache results
      await this.cacheManager.setCachedSearch(queryHash, results);

      this.recordMetrics('search', 'miss', Date.now() - startTime);
      return results;
    } catch (error) {
      console.error(`Error in cached search: ${error}`);
      this.recordMetrics('search', 'error', Date.now() - startTime);

      // Fallback to direct search on error
      return this.fallbackSearch(query, filters, topK);
    }
  }

  public async generateEmbedding(content: string): Promise<number[]> {
    const startTime = Date.now();

    try {
      // Check cache first
      const cachedEmbedding = await this.cacheManager.getCachedEmbedding(content);
      if (cachedEmbedding) {
        this.recordMetrics('embedding', 'hit', Date.now() - startTime);
        return cachedEmbedding;
      }

      // Generate embedding
      const embedding = await this.embeddingService.generateEmbedding(content);

      // Cache embedding
      await this.cacheManager.setCachedEmbedding(content, embedding);

      this.recordMetrics('embedding', 'miss', Date.now() - startTime);
      return embedding;
    } catch (error) {
      console.error(`Error in cached embedding generation: ${error}`);
      this.recordMetrics('embedding', 'error', Date.now() - startTime);

      // Fallback to direct embedding generation
      return this.embeddingService.generateEmbedding(content);
    }
  }

  public async processFile(filePath: string, content: string): Promise<ProcessedFile> {
    const startTime = Date.now();

    try {
      // Check cache first
      const cachedFile = await this.cacheManager.getCachedFileContent(filePath);
      if (cachedFile) {
        this.recordMetrics('processFile', 'hit', Date.now() - startTime);
        return cachedFile;
      }

      // Process file
      const processedFile = await this.documentProcessor.processFile(filePath, content);

      // Cache processed file
      await this.cacheManager.setCachedFileContent(filePath, processedFile);

      this.recordMetrics('processFile', 'miss', Date.now() - startTime);
      return processedFile;
    } catch (error) {
      console.error(`Error in cached file processing: ${error}`);
      this.recordMetrics('processFile', 'error', Date.now() - startTime);

      // Fallback to direct file processing
      return this.documentProcessor.processFile(filePath, content);
    }
  }

  private async fallbackSearch(query: string, filters?: any, topK: number = 10): Promise<SearchResult[]> {
    try {
      // Direct search without caching
      const embedding = await this.embeddingService.generateEmbedding(query);
      return await this.vectorDB.search(embedding, filters, topK);
    } catch (error) {
      console.error(`Fallback search failed: ${error}`);
      return []; // Return empty results as last resort
    }
  }

  private generateQueryHash(query: string, filters?: any, topK: number = 10): string {
    const crypto = require('crypto');
    const content = JSON.stringify({ query, filters, topK });
    return crypto.createHash('sha256').update(content).digest('hex');
  }

  private recordMetrics(operation: string, result: 'hit' | 'miss' | 'error', duration: number): void {
    // This would integrate with a metrics system
    console.log(`Metrics: ${operation} ${result} ${duration}ms`);
  }
}
