Implement a CLI for cache management with the following components:

1. Use commander v11.1.0 for CLI framework
2. Implement commands for cache invalidation
3. Add commands for viewing cache statistics
4. Create commands for manual cache warming
5. Add commands for cache configuration
6. Implement cache debugging tools

Example implementation:
```typescript
import { Command } from 'commander';
import { CacheManager } from './cache-manager';
import { CacheWarmer } from './cache-warmer';
import { CacheAnalytics } from './cache-analytics';
import Table from 'cli-table3';
import chalk from 'chalk';

export class CacheCLI {
  private program: Command;
  private cacheManager: CacheManager;
  private cacheWarmer: CacheWarmer;
  private cacheAnalytics: CacheAnalytics;

  constructor(
    cacheManager: CacheManager,
    cacheWarmer: CacheWarmer,
    cacheAnalytics: CacheAnalytics
  ) {
    this.cacheManager = cacheManager;
    this.cacheWarmer = cacheWarmer;
    this.cacheAnalytics = cacheAnalytics;

    this.program = new Command();
    this.setupCommands();
  }

  public parse(args: string[]): void {
    this.program.parse(args);
  }

  private setupCommands(): void {
    this.program
      .name('cache-cli')
      .description('RAG Cache Management CLI')
      .version('1.0.0');

    // Cache invalidation commands
    this.program
      .command('invalidate')
      .description('Invalidate cache entries')
      .option('-f, --file <path>', 'Invalidate cache for specific file')
      .option('-p, --pattern <pattern>', 'Invalidate cache for pattern')
      .option('-q, --query <query>', 'Invalidate cache for query')
      .option('-a, --all', 'Clear entire cache')
      .action(async (options) => {
        try {
          if (options.all) {
            console.log(chalk.yellow('Clearing entire cache...'));
            await this.cacheManager.clearCache();
            console.log(chalk.green('Cache cleared successfully'));
            return;
          }

          if (options.file) {
            console.log(chalk.yellow(`Invalidating cache for file: ${options.file}`));
            await this.cacheManager.invalidateFile(options.file);
            console.log(chalk.green('File cache invalidated successfully'));
          }

          if (options.pattern) {
            console.log(chalk.yellow(`Invalidating cache for pattern: ${options.pattern}`));
            await this.cacheManager.invalidatePattern(options.pattern);
            console.log(chalk.green('Pattern cache invalidated successfully'));
          }

          if (options.query) {
            console.log(chalk.yellow(`Invalidating cache for query: ${options.query}`));
            const queryHash = this.generateQueryHash(options.query);
            await this.cacheManager.invalidateQuery(queryHash);
            console.log(chalk.green('Query cache invalidated successfully'));
          }

          if (!options.all && !options.file && !options.pattern && !options.query) {
            console.log(chalk.red('No invalidation option specified'));
            console.log('Use --file, --pattern, --query, or --all');
          }
        } catch (error) {
          console.error(chalk.red('Error invalidating cache:'), error);
        }
      });

    // Cache statistics commands
    this.program
      .command('stats')
      .description('View cache statistics')
      .option('-d, --detailed', 'Show detailed statistics')
      .option('-l, --layer <layer>', 'Filter by cache layer (redis, memory)')
      .option('-j, --json', 'Output as JSON')
      .action(async (options) => {
        try {
          const stats = await this.cacheManager.getStats();
          const hitRates = this.cacheAnalytics.calculateHitRate();

          if (options.json) {
            console.log(JSON.stringify({ stats, hitRates }, null, 2));
            return;
          }

          // Basic stats table
          const table = new Table({
            head: ['Cache Layer', 'Entries', 'Hit Rate', 'Memory Usage', 'Avg Response Time']
          });

          if (!options.layer || options.layer === 'redis') {
            table.push([
              'Redis',
              stats.redis.entries || 0,
              `${(hitRates.byLayer['redis'] * 100).toFixed(2)}%`,
              this.formatBytes(stats.redis.memoryBytes || 0),
              `${stats.redis.avgResponseTime || 0}ms`
            ]);
          }

          if (!options.layer || options.layer === 'memory') {
            table.push([
              'In-Memory',
              stats.memory.entries || 0,
              `${(hitRates.byLayer['memory'] * 100).toFixed(2)}%`,
              this.formatBytes(stats.memory.memoryBytes || 0),
              `${stats.memory.avgResponseTime || 0}ms`
            ]);
          }

          table.push([
            'Overall',
            stats.combined.entries || 0,
            `${(hitRates.overall * 100).toFixed(2)}%`,
            this.formatBytes(stats.combined.memoryBytes || 0),
            `${stats.combined.avgResponseTime || 0}ms`
          ]);

          console.log(table.toString());

          // Detailed stats
          if (options.detailed) {
            console.log('\nDetailed Statistics:');

            const detailedTable = new Table({
              head: ['Metric', 'Redis', 'In-Memory', 'Combined']
            });

            detailedTable.push(
              ['Hits', stats.redis.hits || 0, stats.memory.hits || 0, stats.combined.hits || 0],
              ['Misses', stats.redis.misses || 0, stats.memory.misses || 0, stats.combined.misses || 0],
              ['Errors', stats.redis.errors || 0, stats.memory.errors || 0, stats.combined.errors || 0],
              ['Invalidations', stats.redis.invalidations || 0, stats.memory.invalidations || 0, stats.combined.invalidations || 0],
              ['P95 Response Time', `${stats.redis.p95ResponseTime || 0}ms`, `${stats.memory.p95ResponseTime || 0}ms`, `${stats.combined.p95ResponseTime || 0}ms`],
              ['P99 Response Time', `${stats.redis.p99ResponseTime || 0}ms`, `${stats.memory.p99ResponseTime || 0}ms`, `${stats.combined.p99ResponseTime || 0}ms`]
            );

            console.log(detailedTable.toString());
          }
        } catch (error) {
          console.error(chalk.red('Error retrieving cache statistics:'), error);
        }
      });

    // Cache warming commands
    this.program
      .command('warm')
      .description('Warm cache with common queries')
      .option('-p, --project <path>', 'Warm project context')
      .option('-a, --agent <type>', 'Warm agent context')
      .option('-c, --conversation <id>', 'Warm conversation context')
      .option('-s, --schedule <cron>', 'Schedule warming with cron expression')
      .action(async (options) => {
        try {
          if (options.project) {
            console.log(chalk.yellow(`Warming project context: ${options.project}`));
            await this.cacheWarmer.warmProjectContext(options.project);
            console.log(chalk.green('Project context warming initiated'));
          }

          if (options.agent) {
            console.log(chalk.yellow(`Warming agent context: ${options.agent}`));
            await this.cacheWarmer.warmAgentContext(options.agent);
            console.log(chalk.green('Agent context warming initiated'));
          }

          if (options.conversation) {
            console.log(chalk.yellow(`Warming conversation context: ${options.conversation}`));
            await this.cacheWarmer.warmConversationContext(options.conversation);
            console.log(chalk.green('Conversation context warming initiated'));
          }

          if (options.schedule) {
            if (!options.project && !options.agent && !options.conversation) {
              console.log(chalk.red('Must specify what to warm with --project, --agent, or --conversation'));
              return;
            }

            const scheduleId = `schedule_${Date.now()}`;
            const target = options.project || options.agent || options.conversation;
            const type = options.project ? 'project' : options.agent ? 'agent' : 'conversation';

            console.log(chalk.yellow(`Scheduling ${type} warming for ${target} with schedule: ${options.schedule}`));

            // Convert cron to interval for simplicity in this example
            // In a real implementation, use a proper cron parser
            const intervalMs = 3600000; // 1 hour default

            this.cacheWarmer.scheduleWarming({
              id: scheduleId,
              type,
              target,
              intervalMs
            });

            console.log(chalk.green(`Warming scheduled with ID: ${scheduleId}`));
          }

          if (!options.project && !options.agent && !options.conversation) {
            console.log(chalk.red('No warming option specified'));
            console.log('Use --project, --agent, or --conversation');
          }
        } catch (error) {
          console.error(chalk.red('Error warming cache:'), error);
        }
      });

    // Cache debugging commands
    this.program
      .command('debug')
      .description('Debug cache operations')
      .option('-q, --query <query>', 'Check if query is cached')
      .option('-f, --file <path>', 'Check if file is cached')
      .option('-v, --verbose', 'Show verbose output')
      .action(async (options) => {
        try {
          if (options.query) {
            console.log(chalk.yellow(`Checking cache for query: ${options.query}`));
            const queryHash = this.generateQueryHash(options.query);
            const isCached = await this.cacheManager.isQueryCached(queryHash);

            if (isCached) {
              console.log(chalk.green('Query is cached'));

              if (options.verbose) {
                const cachedResult = await this.cacheManager.getCachedSearch(queryHash);
                console.log('Cached result:', cachedResult);
              }
            } else {
              console.log(chalk.red('Query is not cached'));
            }
          }

          if (options.file) {
            console.log(chalk.yellow(`Checking cache for file: ${options.file}`));
            const isCached = await this.cacheManager.isFileCached(options.file);

            if (isCached) {
              console.log(chalk.green('File is cached'));

              if (options.verbose) {
                const cachedFile = await this.cacheManager.getCachedFileContent(options.file);
                console.log('Cached file:', cachedFile);
              }
            } else {
              console.log(chalk.red('File is not cached'));
            }
          }

          if (!options.query && !options.file) {
            console.log(chalk.red('No debug option specified'));
            console.log('Use --query or --file');
          }
        } catch (error) {
          console.error(chalk.red('Error debugging cache:'), error);
        }
      });
  }

  private generateQueryHash(query: string): string {
    const crypto = require('crypto');
    return crypto.createHash('sha256').update(query).digest('hex');
  }

  private formatBytes(bytes: number): string {
    if (bytes === 0) return '0 Bytes';

    const k = 1024;
    const sizes = ['Bytes', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));

    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
  }
}
```

Implement a cache configuration system with the following components:

1. Use dotenv v16.3.1 and config v3.3.9 for configuration management
2. Create environment-specific configurations
3. Implement dynamic configuration updates
4. Add validation for configuration values
5. Create sensible defaults for all settings
6. Add documentation for all configuration options

Example implementation:
```typescript
import dotenv from 'dotenv';
import Joi from 'joi';
import fs from 'fs/promises';
import path from 'path';

// Load environment variables
dotenv.config();

// Configuration schema
const configSchema = Joi.object({
  // Redis cache configuration
  redis: Joi.object({
    host: Joi.string().default('localhost'),
    port: Joi.number().default(6379),
    password: Joi.string().allow('').default(''),
    db: Joi.number().default(0),
    maxMemoryMB: Joi.number().default(100),
    keyPrefix: Joi.string().default('rag:'),
    connectionTimeout: Joi.number().default(5000),
    maxRetriesPerRequest: Joi.number().default(3)
  }).default(),

  // In-memory cache configuration
  memory: Joi.object({
    embeddingsCacheSizeMB: Joi.number().default(20),
    fileContentCacheSizeMB: Joi.number().default(20),
    queryPatternCacheSizeMB: Joi.number().default(10),
    maxEntries: Joi.number().default(10000)
  }).default(),

  // TTL configuration
  ttl: Joi.object({
    fileContentSeconds: Joi.number().default(3600), // 1 hour
    staticDocsSeconds: Joi.number().default(86400), // 24 hours
    embeddingsSeconds: Joi.number().default(43200), // 12 hours
    queryPatternsSeconds: Joi.number().default(1800) // 30 minutes
  }).default(),

  // Cache warming configuration
  warming: Joi.object({
    enabled: Joi.boolean().default(true),
    projectWarmingEnabled: Joi.boolean().default(true),
    agentWarmingEnabled: Joi.boolean().default(true),
    conversationWarmingEnabled: Joi.boolean().default(true),
    warmingIntervalMinutes: Joi.number().default(60),
    maxConcurrentWarmingTasks: Joi.number().default(5)
  }).default(),

  // Cache invalidation configuration
  invalidation: Joi.object({
    fileWatchingEnabled: Joi.boolean().default(true),
    gitIntegrationEnabled: Joi.boolean().default(true),
    semanticInvalidationEnabled: Joi.boolean().default(true),
    semanticSimilarityThreshold: Joi.number().min(0).max(1).default(0.7),
    fileWatchPatterns: Joi.array().items(Joi.string()).default(['**/*.{js,ts,jsx,tsx,md,json}'])
  }).default(),

  // Analytics configuration
  analytics: Joi.object({
    enabled: Joi.boolean().default(true),
    detailedMetrics: Joi.boolean().default(true),
    metricsEndpoint: Joi.string().default('/metrics'),
    metricsIntervalSeconds: Joi.number().default(15)
  }).default(),

  // General configuration
  general: Joi.object({
    logLevel: Joi.string().valid('error', 'warn', 'info', 'debug').default('info'),
    gracefulDegradation: Joi.boolean().default(true),
    debugMode: Joi.boolean().default(false)
  }).default()
}).default();

// Environment-specific configuration files
const envConfigFiles = {
  development: 'config.development.json',
  test: 'config.test.json',
  production: 'config.production.json'
};

export class CacheConfig {
  private static instance: CacheConfig;
  private config: any;
  private configListeners: ((config: any) => void)[] = [];

  private constructor() {
    this.loadConfig();
  }

  public static getInstance(): CacheConfig {
    if (!CacheConfig.instance) {
      CacheConfig.instance = new CacheConfig();
    }
    return CacheConfig.instance;
  }

  public getConfig(): any {
    return { ...this.config };
  }

  public async updateConfig(newConfig: any): Promise<void> {
    try {
      // Validate new configuration
      const { error, value } = configSchema.validate(newConfig, { abortEarly: false });
      if (error) {
        throw new Error(`Configuration validation error: ${error.message}`);
      }

      // Update configuration
      this.config = value;

      // Save to file if in development
      if (process.env.NODE_ENV === 'development') {
        const configFile = envConfigFiles.development;
        const configPath = path.resolve(process.cwd(), configFile);
        await fs.writeFile(configPath, JSON.stringify(this.config, null, 2));
      }

      // Notify listeners
      this.notifyListeners();
    } catch (error) {
      console.error('Error updating configuration:', error);
      throw error;
    }
  }

  public onConfigChange(listener: (config: any) => void): () => void {
    this.configListeners.push(listener);

    // Return unsubscribe function
    return () => {
      this.configListeners = this.configListeners.filter(l => l !== listener);
    };
  }

  private async loadConfig(): Promise<void> {
    try {
      // Determine environment
      const env = process.env.NODE_ENV || 'development';
      const configFile = envConfigFiles[env] || envConfigFiles.development;

      // Load configuration from file
      let fileConfig = {};
      try {
        const configPath = path.resolve(process.cwd(), configFile);
        const configData = await fs.readFile(configPath, 'utf-8');
        fileConfig = JSON.parse(configData);
      } catch (error) {
        console.warn(`Configuration file ${configFile} not found or invalid, using defaults`);
      }

      // Merge with environment variables
      const envConfig = this.loadFromEnvironment();

      // Validate and set defaults
      const mergedConfig = { ...fileConfig, ...envConfig };
      const { error, value } = configSchema.validate(mergedConfig, { abortEarly: false });

      if (error) {
        console.error(`Configuration validation error: ${error.message}`);
        // Use defaults for invalid configuration
        this.config = configSchema.validate({}).value;
      } else {
        this.config = value;
      }
    } catch (error) {
      console.error('Error loading configuration:', error);
      // Use defaults on error
      this.config = configSchema.validate({}).value;
    }
  }

  private loadFromEnvironment(): any {
    const config: any = {};

    // Redis configuration
    if (process.env.REDIS_HOST) config.redis = { ...config.redis, host: process.env.REDIS_HOST };
    if (process.env.REDIS_PORT) config.redis = { ...config.redis, port: parseInt(process.env.REDIS_PORT, 10) };
    if (process.env.REDIS_PASSWORD) config.redis = { ...config.redis, password: process.env.REDIS_PASSWORD };
    if (process.env.REDIS_MAX_MEMORY_MB) config.redis = { ...config.redis, maxMemoryMB: parseInt(process.env.REDIS_MAX_MEMORY_MB, 10) };

    // Memory cache configuration
    if (process.env.MEMORY_EMBEDDINGS_CACHE_SIZE_MB) {
      config.memory = { ...config.memory, embeddingsCacheSizeMB: parseInt(process.env.MEMORY_EMBEDDINGS_CACHE_SIZE_MB, 10) };
    }
    if (process.env.MEMORY_FILE_CONTENT_CACHE_SIZE_MB) {
      config.memory = { ...config.memory, fileContentCacheSizeMB: parseInt(process.env.MEMORY_FILE_CONTENT_CACHE_SIZE_MB, 10) };
    }
    if (process.env.MEMORY_QUERY_PATTERN_CACHE_SIZE_MB) {
      config.memory = { ...config.memory, queryPatternCacheSizeMB: parseInt(process.env.MEMORY_QUERY_PATTERN_CACHE_SIZE_MB, 10) };
    }

    // TTL configuration
    if (process.env.TTL_FILE_CONTENT_SECONDS) {
      config.ttl = { ...config.ttl, fileContentSeconds: parseInt(process.env.TTL_FILE_CONTENT_SECONDS, 10) };
    }
    if (process.env.TTL_STATIC_DOCS_SECONDS) {
      config.ttl = { ...config.ttl, staticDocsSeconds: parseInt(process.env.TTL_STATIC_DOCS_SECONDS, 10) };
    }

    // General configuration
    if (process.env.LOG_LEVEL) config.general = { ...config.general, logLevel: process.env.LOG_LEVEL };
    if (process.env.DEBUG_MODE) config.general = { ...config.general, debugMode: process.env.DEBUG_MODE === 'true' };

    return config;
  }

  private notifyListeners(): void {
    for (const listener of this.configListeners) {
      try {
        listener(this.config);
      } catch (error) {
        console.error('Error in configuration change listener:', error);
      }
    }
  }

  public getDocumentation(): Record<string, string> {
    return {
      'redis.host': 'Redis server hostname',
      'redis.port': 'Redis server port',
      'redis.password': 'Redis server password',
      'redis.db': 'Redis database number',
      'redis.maxMemoryMB': 'Maximum memory usage for Redis cache in MB',
      'redis.keyPrefix': 'Prefix for Redis cache keys',
      'redis.connectionTimeout': 'Redis connection timeout in ms',
      'redis.maxRetriesPerRequest': 'Maximum number of retries per Redis request',

      'memory.embeddingsCacheSizeMB': 'Maximum size of embeddings cache in MB',
      'memory.fileContentCacheSizeMB': 'Maximum size of file content cache in MB',
      'memory.queryPatternCacheSizeMB': 'Maximum size of query pattern cache in MB',
      'memory.maxEntries': 'Maximum number of entries in memory cache',

      'ttl.fileContentSeconds': 'Time-to-live for file content cache in seconds',
      'ttl.staticDocsSeconds': 'Time-to-live for static docs cache in seconds',
      'ttl.embeddingsSeconds': 'Time-to-live for embeddings cache in seconds',
      'ttl.queryPatternsSeconds': 'Time-to-live for query patterns cache in seconds',

      'warming.enabled': 'Enable cache warming',
      'warming.projectWarmingEnabled': 'Enable project context warming',
      'warming.agentWarmingEnabled': 'Enable agent context warming',
      'warming.conversationWarmingEnabled': 'Enable conversation context warming',
      'warming.warmingIntervalMinutes': 'Interval between warming operations in minutes',
      'warming.maxConcurrentWarmingTasks': 'Maximum number of concurrent warming tasks',

      'invalidation.fileWatchingEnabled': 'Enable file watching for cache invalidation',
      'invalidation.gitIntegrationEnabled': 'Enable git integration for cache invalidation',
      'invalidation.semanticInvalidationEnabled': 'Enable semantic similarity-based invalidation',
      'invalidation.semanticSimilarityThreshold': 'Threshold for semantic similarity (0-1)',
      'invalidation.fileWatchPatterns': 'Glob patterns for file watching',

      'analytics.enabled': 'Enable cache analytics',
      'analytics.detailedMetrics': 'Collect detailed metrics',
      'analytics.metricsEndpoint': 'Endpoint for Prometheus metrics',
      'analytics.metricsIntervalSeconds': 'Interval for metrics collection in seconds',

      'general.logLevel': 'Log level (error, warn, info, debug)',
      'general.gracefulDegradation': 'Enable graceful degradation on cache failures',
      'general.debugMode': 'Enable debug mode'
    };
  }
}

// Export singleton instance
export const cacheConfig = CacheConfig.getInstance();
