Implement end-to-end integration and performance testing with the following components:

1. Use Jest v29.7.0 and Supertest v6.3.3 for testing
2. Create realistic test scenarios that mimic user workflows
3. Implement performance benchmarks for cached vs. uncached operations
4. Test cache hit rates under various conditions
5. Test system behavior under load
6. Verify memory usage and leak prevention
7. Test error recovery and graceful degradation

Example implementation:
```typescript
import request from 'supertest';
import { createServer } from '../src/server';
import { CacheManager } from '../src/cache/cache-manager';
import { CacheWarmer } from '../src/cache/cache-warmer';
import { CacheAnalytics } from '../src/cache/cache-analytics';
import { performance } from 'perf_hooks';
import fs from 'fs/promises';
import path from 'path';

describe('RAG Caching System End-to-End Tests', () => {
  let app;
  let server;
  let cacheManager: CacheManager;

  beforeAll(async () => {
    // Initialize server with caching enabled
    const { app: expressApp, server: httpServer, services } = await createServer({
      enableCaching: true
    });

    app = expressApp;
    server = httpServer;
    cacheManager = services.cacheManager;

    // Warm cache with test data
    await warmTestCache(services.cacheWarmer);
  });

  afterAll(async () => {
    // Clear cache and close server
    await cacheManager.clearCache();
    server.close();
  });

  describe('Search Performance Tests', () => {
    it('should be significantly faster for cached queries', async () => {
      // First query (cache miss)
      const startUncached = performance.now();
      const uncachedResponse = await request(app)
        .post('/api/search')
        .send({ query: 'project architecture', filters: {} })
        .expect(200);
      const uncachedDuration = performance.now() - startUncached;

      // Second query (cache hit)
      const startCached = performance.now();
      const cachedResponse = await request(app)
        .post('/api/search')
        .send({ query: 'project architecture', filters: {} })
        .expect(200);
      const cachedDuration = performance.now() - startCached;

      // Verify responses are equivalent
      expect(cachedResponse.body).toEqual(uncachedResponse.body);

      // Verify performance improvement
      console.log(`Uncached query: ${uncachedDuration.toFixed(2)}ms`);
      console.log(`Cached query: ${cachedDuration.toFixed(2)}ms`);
      console.log(`Speedup factor: ${(uncachedDuration / cachedDuration).toFixed(2)}x`);

      // Should be at least 10x faster
      expect(uncachedDuration / cachedDuration).toBeGreaterThan(10);

      // Cached response should be under 100ms
      expect(cachedDuration).toBeLessThan(100);
    });

    it('should maintain high cache hit rates for repeated queries', async () => {
      // Get initial cache stats
      const initialStats = await cacheManager.getStats();

      // Perform multiple queries
      const queries = [
        'project architecture',
        'main components',
        'API endpoints',
        'database schema',
        'authentication flow'
      ];

      // Run each query twice to ensure cache hits
      for (const query of queries) {
        await request(app)
          .post('/api/search')
          .send({ query, filters: {} })
          .expect(200);

        await request(app)
          .post('/api/search')
          .send({ query, filters: {} })
          .expect(200);
      }

      // Get updated cache stats
      const updatedStats = await cacheManager.getStats();

      // Calculate hit rate
      const newHits = updatedStats.combined.hits - initialStats.combined.hits;
      const newMisses = updatedStats.combined.misses - initialStats.combined.misses;
      const hitRate = newHits / (newHits + newMisses);

      console.log(`Cache hit rate: ${(hitRate * 100).toFixed(2)}%`);
      console.log(`Hits: ${newHits}, Misses: ${newMisses}`);

      // Should have at least 50% hit rate (ideally higher)
      expect(hitRate).toBeGreaterThan(0.5);
    });
  });

  describe('Cache Invalidation Tests', () => {
    it('should invalidate cache when files change', async () => {
      // Create a test file
      const testFilePath = path.join(__dirname, 'test-file.txt');
      await fs.writeFile(testFilePath, 'Initial content');

      // Query related to the file
      const query = 'test file content';

      // First query to cache the result
      await request(app)
        .post('/api/search')
        .send({ query, filters: { paths: [testFilePath] } })
        .expect(200);

      // Verify the query is cached
      const queryHash = generateQueryHash(query, { paths: [testFilePath] });
      const isCachedBefore = await cacheManager.isQueryCached(queryHash);
      expect(isCachedBefore).toBe(true);

      // Modify the file
      await fs.writeFile(testFilePath, 'Updated content');

      // Wait for file watcher to detect change
      await new Promise(resolve => setTimeout(resolve, 1000));

      // Verify the query is no longer cached
      const isCachedAfter = await cacheManager.isQueryCached(queryHash);
      expect(isCachedAfter).toBe(false);

      // Clean up
      await fs.unlink(testFilePath);
    });
  });

  describe('Memory Usage Tests', () => {
    it('should maintain stable memory usage under load', async () => {
      // Record initial memory usage
      const initialMemoryUsage = process.memoryUsage().heapUsed;

      // Generate a large number of queries
      const queries = [];
      for (let i = 0; i < 1000; i++) {
        queries.push(`test query ${i}`);
      }

      // Execute queries in batches
      const batchSize = 50;
      for (let i = 0; i < queries.length; i += batchSize) {
        const batch = queries.slice(i, i + batchSize);
        await Promise.all(batch.map(query => {
          return request(app)
            .post('/api/search')
            .send({ query, filters: {} });
        }));
      }

      // Record final memory usage
      const finalMemoryUsage = process.memoryUsage().heapUsed;
      const memoryIncreaseMB = (finalMemoryUsage - initialMemoryUsage) / (1024 * 1024);

      console.log(`Initial memory usage: ${(initialMemoryUsage / (1024 * 1024)).toFixed(2)} MB`);
      console.log(`Final memory usage: ${(finalMemoryUsage / (1024 * 1024)).toFixed(2)} MB`);
      console.log(`Memory increase: ${memoryIncreaseMB.toFixed(2)} MB`);

      // Memory increase should be reasonable (less than 100MB for 1000 queries)
      expect(memoryIncreaseMB).toBeLessThan(100);

      // Force garbage collection if available
      if (global.gc) {
        global.gc();
      }
    });
  });

  describe('Error Recovery Tests', () => {
    it('should gracefully degrade when Redis is unavailable', async () => {
      // Simulate Redis failure
      await cacheManager.simulateRedisFailure(true);

      // Query should still work, falling back to direct search
      const response = await request(app)
        .post('/api/search')
        .send({ query: 'error recovery test', filters: {} })
        .expect(200);

      // Verify we got results despite Redis failure
      expect(response.body.results).toBeDefined();
      expect(response.body.results.length).toBeGreaterThan(0);

      // Restore Redis
      await cacheManager.simulateRedisFailure(false);
    });
  });

  describe('Context Consistency Tests', () => {
    it('should maintain consistent context across conversation sessions', async () => {
      // Start a conversation
      const conversationId = `test-${Date.now()}`;

      // First message with context
      const firstResponse = await request(app)
        .post('/api/conversation')
        .send({
          conversationId,
          message: 'Tell me about the project architecture',
          retainContext: true
        })
        .expect(200);

      // Second message referencing the context
      const secondResponse = await request(app)
        .post('/api/conversation')
        .send({
          conversationId,
          message: 'What are the main components?',
          retainContext: true
        })
        .expect(200);

      // Verify context was retained
      expect(secondResponse.body.usedContext).toBe(true);
      expect(secondResponse.body.contextSources).toBeDefined();
      expect(secondResponse.body.contextSources.length).toBeGreaterThan(0);
    });
  });
});

async function warmTestCache(cacheWarmer: CacheWarmer) {
  // Warm cache with test data
  await cacheWarmer.warmProjectContext(__dirname);
}

function generateQueryHash(query: string, filters: any): string {
  const crypto = require('crypto');
  const content = JSON.stringify({ query, filters });
  return crypto.createHash('sha256').update(content).digest('hex');
